import{_ as e,a0 as l,w as s,s as n,I as a,x as r,a1 as o,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何安裝樹莓派攝像頭模組 | LCTT x X-CMD","titleTemplate":false,"description":"如何安裝樹莓派攝像頭模組 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何安裝樹莓派攝像頭模組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何安裝樹莓派攝像頭模組 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140702 How to install Raspberry Pi camera board","title":"如何安裝樹莓派攝像頭模組","tag":"201408","desc":""},"relativePath":"201408/20140702 How to install Raspberry Pi camera board.md","filePath":"[post].md"}'),m={name:"201408/20140702 How to install Raspberry Pi camera board.md"},u={id:"kristophorus-hadiono",tabindex:"-1"};function f(b,t,g,h,x,y){const p=l("Link");return s(),n("div",null,[t[23]||(t[23]=a("h1",{id:"如何安裝樹莓派攝像頭模組",tabindex:"-1"},[r("如何安裝樹莓派攝像頭模組 "),a("a",{class:"header-anchor",href:"#如何安裝樹莓派攝像頭模組","aria-label":"Permalink to “如何安裝樹莓派攝像頭模組”"},"​")],-1)),a("p",null,[o(p,{href:"http://xmodulo.com/go/picam"},{default:i(()=>[...t[0]||(t[0]=[r("樹莓派攝像頭模組(Pi Cam)",-1)])]),_:1}),t[2]||(t[2]=r("發售於2013年5月。其第一個發佈版本配備了500萬像素的傳感器，通過排線鏈接樹莓派上的CSI接口。而Pi Cam的第二個發佈版本——也被叫做",-1)),o(p,{href:"http://xmodulo.com/go/pinoir"},{default:i(()=>[...t[1]||(t[1]=[r("Pi NoIR",-1)])]),_:1}),t[3]||(t[3]=r("中，配備了相同的傳感器，但沒有紅外線過濾裝置。因此第二版的攝像頭模組就像安全監控攝像機一樣，可以觀測到近紅外線的波長(700 - 1000 nm)，不過當然同時也就犧牲了一定的顯色性。",-1))]),a("p",null,[t[7]||(t[7]=r("本文將會展示",-1)),a("strong",null,[t[5]||(t[5]=r("如何在",-1)),o(p,{href:"http://xmodulo.com/go/raspberrypi"},{default:i(()=>[...t[4]||(t[4]=[r("樹莓派",-1)])]),_:1}),t[6]||(t[6]=r("上安裝攝像頭模組",-1))]),t[8]||(t[8]=r("。我們將使用第一版攝像頭模組來演示。在安裝完攝像頭模組之後，你將會使用三個應用程序來訪問這個模組：raspistill, raspiyuv 和raspivid。其中前兩個應用用來捕捉圖像，第三個應用來捕捉視頻。raspistill 工具生成標準的圖片文件，例如 .jpg 圖像，而 raspiyuv 可以通過攝像頭生成未處理的 raw 圖像文件。",-1))]),t[24]||(t[24]=d(`<h3 id="安裝樹莓派攝像頭模組" tabindex="-1">安裝樹莓派攝像頭模組 <a class="header-anchor" href="#安裝樹莓派攝像頭模組" aria-label="Permalink to “安裝樹莓派攝像頭模組”">​</a></h3><p>按照以下步驟來將樹莓派攝像頭模組連接搭配樹莓派：</p><ol><li><p>找到 CSI 接口(CSI接口在以太網接口旁邊)，掀起深色膠帶。</p></li><li><p>拉起 CSI 接口擋板。</p></li><li><p>拿起你的攝像頭模組，將貼在鏡頭上的塑料保護膜撕掉。確保黃色部分的PCB(有字的一面)是安裝完美的（可以輕輕按一下黃色的部分來保證安裝完美）。</p></li><li><p>將排線插入CSI接口。記住，有藍色膠帶的一面應該面向以太網接口方向。同樣，這時也確認一下排線安裝好了之後，將擋板拉下。</p></li></ol><p><img src="https://farm3.staticflickr.com/2938/14529915452_0910b2e13f_z.jpg" alt=""></p><p>好了，現在你的 Pi Cam 已經準備就緒，可以拍攝照片或視頻了。</p><h3 id="在樹莓派上啓用攝像頭模組" tabindex="-1">在樹莓派上啓用攝像頭模組 <a class="header-anchor" href="#在樹莓派上啓用攝像頭模組" aria-label="Permalink to “在樹莓派上啓用攝像頭模組”">​</a></h3><p>在安裝完攝像頭模組之後，首先要確認你已經升級了樹莓派系統並應用了最新的固件。可以輸入以下命令來操作：</p><pre><code>$ sudo apt-get update
$ sudo apt-get upgrade 
</code></pre><p>運行樹莓派配置工具來激活攝像頭模組：</p><pre><code>$ sudo raspi-config 
</code></pre><p>移動光標至菜單中的 &quot;Enable Camera（啓用攝像頭）&quot;，將其設為Enable（啓用狀態）。完成之後重啓樹莓派。</p><p><img src="https://farm4.staticflickr.com/3837/14530918915_e68ca0beef_z.jpg" alt=""></p><p><img src="https://farm3.staticflickr.com/2922/14344284230_6cabbe2522_z.jpg" alt=""></p><p><img src="https://farm3.staticflickr.com/2923/14529915362_7a437a53cb_z.jpg" alt=""></p><p>安裝完攝像頭模組後的完成照：</p><p><img src="https://farm3.staticflickr.com/2924/14551046653_1c37e077fd_z.jpg" alt=""></p><h3 id="通過攝像頭模組拍照" tabindex="-1">通過攝像頭模組拍照 <a class="header-anchor" href="#通過攝像頭模組拍照" aria-label="Permalink to “通過攝像頭模組拍照”">​</a></h3><p>在重啓完樹莓派後，我們就可以使用Pi Cam了。要用它來拍攝照片的話，可以從命令列運行raspistill：</p><pre><code>$ raspistill -o keychain.jpg -t 2000 
</code></pre><p>這句命令將在 2000ms 後拍攝一張照片，然後保存為 keychain.jpg。下面就是一張由 Pi Cam 拍攝的我的小熊公仔鑰匙鏈。</p><p><img src="https://farm4.staticflickr.com/3845/14530919095_ea0f37045a_z.jpg" alt=""></p><p>raspiyuv 工具用法差不多，只不過拍攝得到的是一張未處理過的raw圖像。</p><h3 id="通過攝像頭模組拍視頻" tabindex="-1">通過攝像頭模組拍視頻 <a class="header-anchor" href="#通過攝像頭模組拍視頻" aria-label="Permalink to “通過攝像頭模組拍視頻”">​</a></h3><p>想要用攝像頭模組拍一段視頻的話，可以從命令列運行 raspivid 工具。下面這句命令會按照默認配置(長度5秒，分辨率1920x1080，比特率 17Mbps)拍攝一段視頻。</p><pre><code>$ raspivid -o mykeychain.h264
</code></pre><p>如果你想改變拍攝時長，只要通過 &quot;-t&quot; 選項來設置你想要的長度就行了（單位是毫秒）。</p><pre><code>$ raspivid -o mykeychain.h264 -t 10000
</code></pre><p>使用 &quot;-w&quot; 和 &quot;-h&quot; 選項將分辨率降為 1280x720...</p><pre><code>$ raspivid -o mykeychain.h264 -t 10000 -w 1280 -h 720
</code></pre><p>raspivid 的輸出是一段未壓縮的 H.264 視頻流，而且這段視頻不含聲音。為了能被通常的視頻播放器所播放，這個 raw 的 H.264 視頻還需要轉換。可以使用 gpac 包中所帶有的 MP4Box 應用。</p><p>在 Raspbian 上安裝 gpac，輸入命令：</p><pre><code>$ sudo apt-get install -y gpac 
</code></pre><p>然後將這段 raw 的 H.264 格式的視頻流轉換為每秒30幀的 .mp4 格式視頻：</p><pre><code>$ MP4Box -fps 30 -add keychain.h264 keychain.mp4 
</code></pre><p>視頻長度為10秒，使用默認分辨率以及比特率。下面是一段通過 Pi Camera 拍攝的一段實例視頻。</p><p>注：youtube視頻地址</p>`,36)),t[25]||(t[25]=a("iframe",{width:"615",height:"376",frameborder:"0",src:"http://www.youtube.com/embed/3uyR2AVVwAU?version=3&rel=1&fs=1&showsearch=0&showinfo=1&iv_load_policy=1&wmode=transparent",type:"text/html",class:"youtube-player"},null,-1)),t[26]||(t[26]=a("p",null,"如果想要獲取 raspistill, raspiyuv 和 raspivid 的完整命令列選項，不加任何選項直接運行以上命令即可。",-1)),t[27]||(t[27]=a("hr",null,null,-1)),a("h3",u,[o(p,{href:"http://hadiono.org/blog"},{default:i(()=>[...t[9]||(t[9]=[r("Kristophorus Hadiono",-1)])]),_:1}),t[10]||(t[10]=r()),t[11]||(t[11]=a("a",{class:"header-anchor",href:"#kristophorus-hadiono","aria-label":"Permalink to “Kristophorus Hadiono”"},"​",-1))]),t[28]||(t[28]=a("p",null,"Kristophorus Hadiono是一名 Linux 愛好者，並且是印度尼西亞一所民辦高等學府的教師。他在日常生活中使用 Linux，也在給學生們教學的時候使用。他現在仍靠着政府的獎學金，在泰國曼谷的一所民辦大學繼續着學業。",-1)),t[29]||(t[29]=a("hr",null,null,-1)),a("p",null,[t[13]||(t[13]=r("via: ",-1)),o(p,{href:"http://xmodulo.com/2014/07/install-raspberry-pi-camera-board.html"},{default:i(()=>[...t[12]||(t[12]=[r("http://xmodulo.com/2014/07/install-raspberry-pi-camera-board.html",-1)])]),_:1})]),a("p",null,[t[16]||(t[16]=r("譯者：",-1)),o(p,{href:"https://github.com/ThomazL"},{default:i(()=>[...t[14]||(t[14]=[r("ThomazL",-1)])]),_:1}),t[17]||(t[17]=r(" 校對：",-1)),o(p,{href:"https://github.com/reinoir"},{default:i(()=>[...t[15]||(t[15]=[r("reinoir",-1)])]),_:1})]),a("p",null,[t[20]||(t[20]=r("本文由 ",-1)),o(p,{href:"https://github.com/lctt/translateproject"},{default:i(()=>[...t[18]||(t[18]=[r("lctt",-1)])]),_:1}),t[21]||(t[21]=r(" 原創翻譯，",-1)),o(p,{href:"http://linux.cn/"},{default:i(()=>[...t[19]||(t[19]=[r("linux中國",-1)])]),_:1}),t[22]||(t[22]=r(" 榮譽推出",-1))])])}const w=e(m,[["render",f]]);export{P as __pageData,w as default};
